#include "Graphics/Utilities/EnvironmentHybridCertificate.h"
#include <cstdio>
#include <cstdlib>
#include "Graphics/RHI/Core/FrameSlotCompletion.h"
using namespace primal;using namespace primal::graphics;
static void check(bool ok,const char* msg){if(!ok){std::fprintf(stderr,"[ENV_FIELD_CERT_TEST] FAIL %s\n",msg);std::exit(1);}}
int main(){using namespace environment_hybrid;ray_geometry::SceneBVH scene;check(ray_geometry::LoadSceneBVH(kScenePath,kSourceDigest,scene),"load fixed geometry");std::vector<u8> field;check(Verify(scene,field),"valid field and scene");auto bad=field;bad[0]^=1;check(!VerifyField(scene,bad),"field corruption rejected");bad=field;bad[20]^=1;check(!VerifyField(scene,bad),"field map or metadata corruption rejected");bad=field;u32 leafBase=0;std::memcpy(&leafBase,bad.data()+5*4,4);bad[leafBase*4]^=1;check(!VerifyField(scene,bad,false),"leaf membership rejected independent of hash");bad=field;bad[8*4]^=1;check(!VerifyField(scene,bad,false),"wrong root rejected independent of hash");
 auto altered=scene;altered.top[0].lo[0]+=1.f;check(!SamePayload(altered,scene),"TLAS content");altered=scene;altered.bottom[0].lo[0]+=1.f;check(!SamePayload(altered,scene),"BLAS content");altered=scene;altered.triangles[0].a[0]+=1.f;check(!SamePayload(altered,scene),"triangle content");altered=scene;altered.instances[0].inverse_rows[0][0]+=1.f;check(!SamePayload(altered,scene),"instance content");altered=scene;altered.instances.pop_back();check(!SamePayload(altered,scene),"logical length");
 int producer=0,other=0;Binding a{};a.producer=&producer;a.producer_id=NewProducerId();a.epoch=3;a.digest=4;a.generation=5;a.completion=6;a.slot=1;a.ready=true;for(u32 i=0;i<4;++i){a.handles[i]=10+i;a.allocated[i]=64;a.logical[i]=48;}check(SameBinding(a,a),"valid binding");auto b=a;b.producer=&other;check(!SameBinding(a,b),"producer");b=a;b.producer_id=NewProducerId();check(!SameBinding(a,b),"same address different producer generation");b=a;b.epoch++;check(!SameBinding(a,b),"epoch");b=a;b.digest++;check(!SameBinding(a,b),"digest");b=a;b.generation++;check(!SameBinding(a,b),"generation");b=a;b.completion++;check(!SameBinding(a,b),"completion");b=a;b.slot++;check(!SameBinding(a,b),"slot");b=a;b.ready=false;check(!SameBinding(a,b),"failed publication");for(u32 i=0;i<4;++i){b=a;b.handles[i]++;check(!SameBinding(a,b),"handle");b=a;b.allocated[i]++;check(!SameBinding(a,b),"allocated");b=a;b.logical[i]++;check(!SameBinding(a,b),"logical");}primal::graphics::rhi::FrameSlotCompletion slots;check(!slots.CanReuse(1,0),"unknown completion");check(slots.Publish(1)&&slots.CanReuse(1,0),"published completion");auto serial=slots.Serial(1);check(!slots.CanReuse(1,serial),"completion cannot be reused");slots.Invalidate();check(!slots.CanReuse(1,0),"invalidated completion");check(slots.Publish(2)&&!slots.CanReuse(1,serial),"wrong slot completion");check(slots.Publish(1)&&slots.CanReuse(1,serial),"fresh completion");std::puts("Environment hybrid certificate CPU tests passed");return 0;}
